/* Owner review helpers: previews never write data; duplicate links are highlighted before saving. */
window.SaiOwnerWorkflow=(()=>{
 const allowed=()=>user?.role==='admin';
 const canonical=value=>{try{const u=new URL(value);return u.hostname.toLowerCase().replace(/^www\./,'')+u.pathname.replace(/\/$/,'')+u.search;}catch{return '';}};
 function mountEditor(form,kind,original,snapshot){
  if(!allowed())return;
  const footer=document.createElement('div');footer.className='owner-editor-tools';footer.innerHTML='<button type="button" class="button outline" data-owner-preview>معاينة قبل الحفظ</button><p class="muted">المعاينة لا تحفظ التعديلات ولا تنشرها.</p><div class="owner-duplicate" hidden role="status"></div><section class="owner-preview" hidden aria-label="معاينة المحتوى"></section>';form.insertBefore(footer,form.querySelector('[type=submit]'));
  const area=footer.querySelector('.owner-preview'),warning=footer.querySelector('.owner-duplicate');let duplicateKey='';
  const duplicates=()=>{const fd=new FormData(form),url=canonical(fd.get(kind==='provider'?'official_url':'source_url'));return (kind==='provider'?snapshot.providers||[]:snapshot.opportunities||[]).filter(row=>row.id!==original.id&&url&&canonical(kind==='provider'?row.official_url:row.source_url)===url);};
  function warn(){const rows=duplicates(),key=rows.map(x=>x.id).join(',');if(key===duplicateKey)return rows;duplicateKey=key;warning.hidden=!rows.length;warning.innerHTML=rows.length?'<strong>هذا الرابط مستخدم في محتوى موجود.</strong><p>'+rows.map(x=>esc(x.title||x.name)).join('، ')+'</p><p>راجعي المحتوى الموجود قبل إضافة نسخة أخرى.</p>':'';return rows;}
  function preview(){const fd=new FormData(form),v=Object.fromEntries(fd),fields=fd.getAll('fields').map(id=>snapshot.fields.find(f=>f.id===id)?.label).filter(Boolean);let body,title;
   if(kind==='provider'){title=v.name;body=providerDetail({name:v.name,url:v.official_url,description:v.description,details:v.details,fields,language:v.language,cost:v.cost,contentTypes:String(v.content_types||'').split(/[,،]/).map(x=>x.trim()).filter(Boolean),guidance:{levels:fd.getAll('levels'),languages:fd.getAll('languages'),cost:v.cost_kind}});}
   else{title=v.title;const locked=original.registration_locked;const mode=locked?original.registration_kind:v.registration_kind;const instant=locked?original.deadline_at:mode==='exact'&&v.deadline_at?new Date(v.deadline_at+':00+03:00').toISOString():mode==='date'&&v.registration_date?new Date(Date.parse(v.registration_date+'T00:00:00+03:00')+86400000).toISOString():null;body=opportunityDetail({title:v.title,description:v.description,originalText:v.original_text,type:v.type==='hackathon'?'هاكاثون':'مسابقة',sourceName:v.source_name,sourceUrl:v.source_url,registrationUrl:v.registration_url,fields,mode:v.mode,registrationKind:mode,deadlineAt:instant,deadline:v.deadline_text||v.registration_date||''});}
   area.innerHTML='<h3>'+esc(title||'معاينة المحتوى')+'</h3>'+body;if(kind==='provider'){const logo=$('#owner-logo-preview')?.cloneNode(true);if(logo){logo.removeAttribute('id');area.prepend(logo);}}area.hidden=false;footer.querySelector('[data-owner-preview]').textContent='تحديث المعاينة';area.scrollIntoView({block:'nearest',behavior:'smooth'});warn();
  }
  footer.querySelector('[data-owner-preview]').onclick=()=>{if(form.reportValidity())preview();};
  form.addEventListener('input',()=>{warn();if(!area.hidden){area.hidden=true;footer.querySelector('[data-owner-preview]').textContent='تحديث المعاينة';}});
  form.addEventListener('change',warn);
  warn();
 }
 async function dashboard(snapshot){if(!allowed())return;const host=$('#admin-content'),version=accountVersion;
  const tasks=document.createElement('section');tasks.className='owner-work-queue';tasks.innerHTML=`<h2>مهام المتابعة</h2><div class="owner-task-grid"><button class="owner-task" data-owner-task="stories"><strong>${snapshot.experiences.filter(x=>x.status==='pending').length}</strong><span>تجارب تنتظر المراجعة</span></button><button class="owner-task" data-owner-task="providers"><strong>${(snapshot.providers||[]).filter(x=>!x.reviewed_at||Date.now()-Date.parse(x.reviewed_at)>90*86400000).length}</strong><span>جهات تحتاج تحديثًا</span></button><button class="owner-task" data-owner-task="drafts"><strong>${snapshot.opportunities.filter(x=>x.status==='draft').length+(snapshot.providers||[]).filter(x=>x.status==='draft').length}</strong><span>مسودات لاستكمالها</span></button></div><p class="muted">لإعادة محتوى مخفي: اختاري تصفية «مخفية»، ثم افتحي تعديل وغيّري الحالة إلى منشورة. تبقى مواعيد الفرص الأصلية مثبتة.</p>`;host.querySelector('.owner-summary')?.replaceWith(tasks);
  tasks.onclick=event=>{const action=event.target.closest('[data-owner-task]')?.dataset.ownerTask;if(!action)return;const ids=action==='stories'?['owner-story-filter']:action==='providers'?['owner-provider-filter']:['owner-opportunity-filter','owner-provider-filter'];for(const id of ids){const el=$('#'+id);el.value=action==='stories'?'pending':action==='providers'?'review':'draft';el.dispatchEvent(new Event('change'));}$('#'+ids[0]).scrollIntoView({block:'center',behavior:'smooth'});$('#'+ids[0]).focus({preventScroll:true});};
  const section=document.createElement('section');section.className='owner-section';section.id='owner-history';section.innerHTML='<h2>آخر عمليات الإدارة</h2><p role="status">جارٍ تحميل السجل…</p>';host.append(section);
  try{const rows=await api.ownerHistory();if(!allowed()||version!==accountVersion||!section.isConnected)return;const labels={save_opportunity:'حفظ فرصة',save_provider:'حفظ جهة تعلم',experience_published:'نشر تجربة',experience_rejected:'طلب تعديل تجربة',experience_pending:'إعادة تجربة للمراجعة',report_resolved:'معالجة بلاغ',report_dismissed:'إغلاق بلاغ',report_open:'إعادة فتح بلاغ'};section.innerHTML='<h2>آخر عمليات الإدارة</h2><p class="muted">آخر 50 عملية محفوظة، مع وقت التنفيذ. السجل لا يمثل نسخًا سابقة قابلة للاستعادة.</p><ol class="owner-history-list">'+rows.map(row=>'<li><strong>'+esc(labels[row.action]||'تحديث محتوى')+'</strong><span>'+esc(row.title||'محتوى تمت مراجعته')+'</span><time>'+esc(new Intl.DateTimeFormat(document.documentElement.lang==='en'?'en-GB':'ar-SA-u-ca-gregory',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Riyadh'}).format(new Date(row.created_at)))+'</time></li>').join('')+'</ol>'+(rows.length?'':'<p>لا توجد عمليات مسجلة بعد.</p>');}
  catch{if(section.isConnected&&allowed())section.innerHTML='<h2>آخر عمليات الإدارة</h2><p>تعذّر تحميل السجل.</p><button type="button" class="text-link" data-owner-reload>إعادة المحاولة</button>';}
 }
 return {mountEditor,dashboard};
})();
